"""Terminal speech reviewed through shared helper returns and bookkeeping callbacks."""
ROWS = []
def add(key, labels, subject, lines):
    replies = [line.strip() for line in lines.split('|')]
    assert len(replies) == 11, (key, len(replies))
    ROWS.append(dict(key='hoenn_callback_' + key, labels=labels.split(), subject=subject, replies=replies))

